import api from './api';

/**
 * Servicio de Menú Público — el que ve el cliente al escanear el QR de su
 * mesa. Sin autenticación: la ruta es pública (ver App.jsx, /menu/:branchCode).
 */
export const getPublicMenu = (branchCode) => api.get(`/menu/${branchCode}`);
